<?php
declare(strict_types=1);require __DIR__.'/app/bootstrap.php';if(empty($_SESSION['reseller_id'])){header('Location: reseller-login.php');exit;}$rid=(int)$_SESSION['reseller_id'];$error='';$success='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$lines=preg_split('/[\r\n]+/',trim($_POST['codes']??''),-1,PREG_SPLIT_NO_EMPTY);$entries=[];foreach($lines as $line){$parts=preg_split('/[:;,\s]+/',trim($line),2);if(count($parts)===2)$entries[]=[strtoupper($parts[0]),strtoupper($parts[1])];}if(!$entries||count($entries)>500)$error='Informe códigos e respectivas chaves, um por linha, no formato ED00000001:CHAVE.';else{$pdo=db();$pdo->beginTransaction();try{$find=$pdo->prepare("SELECT id,activation_code_hash FROM plaques WHERE code=? AND status='stock' AND reseller_id IS NULL FOR UPDATE");$assign=$pdo->prepare("UPDATE plaques SET reseller_id=? WHERE id=? AND status='stock' AND reseller_id IS NULL");$done=[];foreach($entries as [$code,$key]){if(!preg_match('/^ED[0-9]{8}$/',$code)||!preg_match('/^[A-Z0-9]{8,16}$/',$key))throw new RuntimeException('Formato inválido para a placa '.$code.'.');$find->execute([$code]);$p=$find->fetch();if(!$p||empty($p['activation_code_hash'])||!password_verify($key,$p['activation_code_hash']))throw new RuntimeException('Placa '.$code.' não encontrada, indisponível ou chave não confere.');$assign->execute([$rid,$p['id']]);if($assign->rowCount()!==1)throw new RuntimeException('Não foi possível registrar '.$code);$done[]=$code;}$pdo->prepare("INSERT INTO reseller_kit_orders(reseller_id,kit_size,status) VALUES(?,?,'delivered')")->execute([$rid,count($done)]);$pdo->commit();$success=count($done).' placa(s) adicionada(s) ao seu estoque.';}catch(Throwable $e){$pdo->rollBack();$error=$e instanceof RuntimeException?$e->getMessage():'Erro ao registrar as placas.';}}}
$q=db()->prepare("SELECT code,created_at FROM plaques WHERE reseller_id=? AND status='stock' ORDER BY id DESC");$q->execute([$rid]);$rows=$q->fetchAll();
layout_start('Painel do revendedor');
?><div class="heading"><div><span class="eyebrow">PORTAL DO REVENDEDOR</span><h1>Olá, <?=e($_SESSION['reseller_name']??'Revendedor')?></h1><p>Cadastre os kits comprados nos marketplaces usando os códigos e as chaves impressas.</p></div><a class="button secondary" href="reseller-logout.php">Sair</a></div><?php if($error):?><div class="notice error"><?=e($error)?></div><?php endif;?><?php if($success):?><div class="notice"><?=e($success)?></div><?php endif;?><form method="post" class="panel"><?=client_csrf_field()?><h2>Adicionar placas ao meu estoque</h2><p>Informe uma placa por linha, no formato <b>ED00000001:CHAVE</b>. A chave é apenas conferida e não é consumida; o comprador continuará podendo ativar a placa com ela.</p><label>Código e chave de ativação<textarea name="codes" rows="6" placeholder="ED00000001:AB12CD34EF&#10;ED00000002:CD34EF56GH" required></textarea></label><button>Validar e registrar kit</button></form><section class="panel"><h2>Meu estoque (<?=count($rows)?>)</h2><div class="tablewrap"><table><thead><tr><th>Placa</th><th>Link QR/NFC</th><th>Estado</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?=e($r['code'])?></b></td><td><a href="<?=e(app_url('r/'.$r['code']))?>" target="_blank"><?=e(app_url('r/'.$r['code']))?></a></td><td>Disponível</td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="3">Nenhuma placa registrada ainda.</td></tr><?php endif;?></tbody></table></div></section><?php layout_end();?>